"""Find the predictions.csv output from the job."""
import hopsworks
import os

JOB_NAME = "trainjob7a8727"

def list_dir(dataset_api, path, depth=0):
    try:
        items = dataset_api.list(path, sort_by="NAME")
        for item in items:
            indent = "  " * depth
            print(f"{indent}{item['attributes']['path']} ({item['attributes']['type']})")
            if item['attributes']['type'] == 'DIRECTORY' and depth < 2:
                list_dir(dataset_api, item['attributes']['path'], depth+1)
    except Exception as e:
        print(f"{'  '*depth}Error listing {path}: {e}")

def main():
    project = hopsworks.login()
    dataset_api = project.get_dataset_api()

    # Check several possible locations for predictions.csv
    search_paths = [
        f"Resources/{JOB_NAME}",
        f"Resources/jobs/{JOB_NAME}",
        "Resources",
        "Logs",
    ]

    for path in search_paths:
        print(f"\n=== Listing: {path} ===")
        list_dir(dataset_api, path)

    # Also try to search for predictions.csv specifically
    print("\n=== Searching for predictions.csv ===")
    try:
        results = dataset_api.find("predictions.csv")
        for r in results:
            print(f"Found: {r}")
    except Exception as e:
        print(f"Search failed: {e}")

if __name__ == "__main__":
    main()

